import { useState, useEffect } from 'react';
import io from 'socket.io-client';
import { toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';

/**
 * Custom hook to manage a Socket.IO client connection.
 *
 * @param {function} navigate Function to navigate between routes.
 * @param {object} userVideo Ref object for the user's video element.
 * @param {function} setStream Function to set the user's media stream.
 * @param {function} setIsHosting Function to update the hosting state.
 * @param {function} setIsJoined Function to update the joined state.
 * @returns {object} The Socket.IO client instance.
 */
const useSocket = (navigate, userVideo, setStream, setIsHosting, setIsJoined) => {
  const [socket, setSocket] = useState(null);

  useEffect(() => {
    // Establish a connection to the Socket.IO server
    const newSocket = io.connect('http://localhost:3001');
    setSocket(newSocket);

    // Event listener for 'host' event
    newSocket.on('host', () => {
      setIsHosting(true);
      // Navigate to the meeting page and pass the state of audio and video tracks
      navigate('/meeting', {
        state: {
          isMicEnabled: userVideo.current.srcObject && userVideo.current.srcObject.getAudioTracks()[0].enabled,
          isCamEnabled: userVideo.current.srcObject && userVideo.current.srcObject.getVideoTracks()[0].enabled
        }
      });
    });

    // Event listener for 'join' event
    newSocket.on('join', () => {
      setIsJoined(true);
      navigate('/meeting', {
        state: {
          isMicEnabled: userVideo.current.srcObject && userVideo.current.srcObject.getAudioTracks()[0].enabled,
          isCamEnabled: userVideo.current.srcObject && userVideo.current.srcObject.getVideoTracks()[0].enabled
        }
      });
    });

    // Event listener for 'no-host' event
    newSocket.on('no-host', () => {
      toast.error('No Hosted Meetings'); // Display an error toast if no meeting is hosted
    });

    // Event listener for 'host-left' event
    newSocket.on('host-left', () => {
      toast.info('Host has left the meeting'); // Display an info toast when host leaves
      navigate('/'); // Navigate back to the lobby
    });

    // Request access to the user's camera and microphone
    navigator.mediaDevices.getUserMedia({ video: true, audio: true })
      .then(stream => {
        userVideo.current.srcObject = stream; // Assign the media stream to the video element
        setStream(stream); // Update the stream state
      })
      .catch(err => {
        console.error('Error accessing media devices.', err);
        toast.error('Error accessing media devices'); // Display an error toast if access is denied
      });

    // Cleanup function to close the socket connection when the component unmounts
    //return () => newSocket.close();
  }, [navigate, setStream, setIsHosting, setIsJoined, userVideo]);

  return socket;
};

export default useSocket;
